import React, { useState, useEffect } from 'react';

// Fallback story cards matching actual site layout
const FALLBACK_STORIES = [
  {
    id: 1,
    title: { rendered: 'The Summit Mindset' },
    excerpt: { rendered: '<p>Every challenging trek teaches me that sustained effort, strategic planning, and unwavering focus are the only paths to greatness—both on mountains and in business.</p>' },
    date: '2024-02-01',
    link: 'https://pankajbiswas.com',
    _image: 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=600&h=400&fit=crop',
    _month: 'February 2024',
  },
  {
    id: 2,
    title: { rendered: 'Finding Clarity in Serenity' },
    excerpt: { rendered: '<p>In the silence of mountain valleys, I discovered that true innovation happens when we step away from noise and reconnect with our deepest purpose and vision.</p>' },
    date: '2024-01-01',
    link: 'https://pankajbiswas.com',
    _image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=600&h=400&fit=crop',
    _month: 'January 2024',
  },
  // Add more fallback stories...
];

const Stories = () => {
  const [stories, setStories] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  const postsPerPage = 12;
  const category = 'travel'; // We will automatically look up the ID for this slug

  useEffect(() => {
    const fetchStories = async () => {
      try {
        let categoryId = '';
        if (category) {
          // If category is a slug (not a number), we need to fetch its ID first
          if (isNaN(category)) {
            const catRes = await fetch(`/wp-json/wp/v2/categories?slug=${category}`);
            if (catRes.ok) {
              const catData = await catRes.json();
              if (catData.length > 0) {
                categoryId = catData[0].id;
              }
            }
          } else {
            categoryId = category;
          }
        }

        const categoryQuery = categoryId ? `&categories=${categoryId}` : '';
        const response = await fetch(
          `/wp-json/wp/v2/posts?per_page=${postsPerPage}&_embed=1${categoryQuery}&orderby=date&order=desc&page=${currentPage}`
        );

        if (!response.ok) {
          throw new Error(`Failed to fetch stories, status code: ${response.status}`);
        }

        const data = await response.json();

        // Get total pages from the response headers
        const totalPagesHeader = response.headers.get('X-WP-TotalPages');
        const totalPages = totalPagesHeader ? parseInt(totalPagesHeader) : 1;
        setTotalPages(totalPages);
        setStories(data);

        setLoading(false);
      } catch (error) {
        console.error('Error fetching stories:', error);
        setStories(FALLBACK_STORIES); // Use fallback stories if error occurs
        setError(true);
        setLoading(false);
      }
    };

    fetchStories();
  }, [currentPage]);

  const goToPage = (page) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  return (
    <>
      <section className="stories-section">
        <div className="container">
          {loading ? (
            <p>Loading stories...</p>
          ) : error ? (
            <p>Error loading stories. Displaying fallback content.</p>
          ) : (
            stories.map((story) => (
              <div key={story.id} className="story-card">
                <img src={story._image} alt={story.title.rendered} />
                <h2>{story.title.rendered}</h2>
                <div dangerouslySetInnerHTML={{ __html: story.excerpt.rendered }} />
                <a href={story.link} target="_blank" rel="noopener noreferrer">Read more</a>
              </div>
            ))
          )}

          {/* Pagination */}
          <nav className="pagination-nav">
            <button onClick={() => goToPage(Math.max(currentPage - 1, 1))} disabled={currentPage === 1}>
              ‹ Previous
            </button>
            {Array.from({ length: totalPages }, (_, i) => i + 1).map((pg) => (
              <button
                key={pg}
                onClick={() => goToPage(pg)}
                style={{
                  background: currentPage === pg ? '#d4af37' : 'transparent',
                  border: '1px solid rgba(212,175,55,0.3)',
                  color: currentPage === pg ? '#0d0d0d' : '#d4af37',
                  padding: '0.5rem 0.9rem',
                  cursor: 'pointer',
                }}
              >
                {pg}
              </button>
            ))}
            <button onClick={() => goToPage(currentPage + 1)} disabled={currentPage === totalPages}>
              Next ›
            </button>
          </nav>
        </div>
      </section>

      {/* Call to Action */}
      <section className="cta-luxury">
        <div className="container-fluid px-5">
          <div className="cta-content">
            <h2>Ready to Transform Your Digital Future?</h2>
            <p>Let’s discuss your vision and create a strategic roadmap for unprecedented growth.</p>
            <a href="/contact" className="btn btn-gold btn-lg">Schedule Free Strategy Call</a>
          </div>
        </div>
      </section>
    </>
  );
};

export default Stories;
